def lengthOfLongestSubstring(s: str) -> int:
    max_len = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            if len(substring) == len(set(substring)):
                if len(substring) > max_len:
                    max_len = len(substring)
    return max_len

